import { interpolateString, isCollection, isFunction, isList, isString, removeNilValues, toList } from '../utils'
import { cloneDeep, get, hasObjectValue as hasPlainObjectValue, isObject as isPlainObject } from '../utils/object'
import { FIELD } from '../modules/variables'
import Render from './Render'

/**
 * Whether a cell's definition renders a form control that names nothing: no `label`, `aria-label` or `aria-labelledby`.
 * A table gives such a field its column's header for a name.
 */
export const isUnnamedField = (definition: Meta): boolean => [
    FIELD.TYPE.INPUT, FIELD.TYPE.SELECT, FIELD.TYPE.DROPDOWN, FIELD.TYPE.CHECKBOX, FIELD.TYPE.TOGGLE, FIELD.TYPE.SLIDER,
].indexOf(definition.view) !== -1
    && definition.label == null && definition['aria-label'] == null && definition['aria-labelledby'] == null

// Non-narrowing, on purpose: a meta node checked with these stays `Meta`, open JSON, instead of
// becoming the `Record<string, unknown>` the util's type guard narrows it to.
const isObject: (value: unknown) => boolean = isPlainObject
const hasObjectValue: (value: unknown) => boolean = hasPlainObjectValue

/**
 * A meta node: open JSON, read and rewritten in place by key. `any`, deliberately: what a node may
 * hold is the contract `validateMeta` checks at runtime and the published types describe, not
 * something this transform can know ahead of reading it.
 */
type Meta = Record<string, any>

/** A handler a meta names: called with the caller's arguments first, then the meta's. */
type Handler = (...args: any[]) => any

/** The handler and value-transform registries `rules.tsx` builds for one document. */
export type FuncConfig = {
    data?: unknown
    fieldFunc: Record<string, Handler>
    fieldNormalizer: Record<string, Handler>
    fieldParser: Record<string, Handler>
    fieldValidation: Record<string, Handler>
    fieldMethods: Record<string, Handler>
    [key: string]: unknown
}

/** What resolving a meta's handlers is given: the registries, and where the node sits. */
type FunctionConfig = FuncConfig & {
    instance?: any
    funcNames?: string[]
    fallback?: unknown
    relativeIndex?: unknown
    _data?: unknown
    rowValue?: unknown
}

/** What `metaToProps` is given: the document, the data it renders against, and where a node sits. */
export type TransformConfig = {
    data?: unknown
    _data?: unknown
    form?: unknown
    instance?: any
    relativePath?: string
    relativeIndex?: number | string
    funcConfig: FuncConfig
    [key: string]: unknown
}

// `onFocus` and `onBlur` since 2026-10-06: before, a meta's reached the component as a string or as the
// value its object form resolved to, and replaced the field's own handler (the field hosts in `modules/form`).
const FUNCTION_NAMES = ['onClick', 'onChange', 'onDone', 'onFocus', 'onBlur']

/** Declarations that describe the meta document rather than a component. See metaToProps. */
const CONTRACT_ATTRIBUTES = ['$schema', 'metaVersion']

/**
 * Author annotations. Permitted anywhere by the (deliberately open) meta schema, meaningless
 * to the renderer, and not an HTML attribute. See metaToProps.
 */
const COMMENT_ATTRIBUTES = ['_comment']

/** Meta attributes that are never component props, dropped on the way from meta.json to props. */
const NON_PROP_ATTRIBUTES = [...CONTRACT_ATTRIBUTES, ...COMMENT_ATTRIBUTES]

/**
 * A CELL A `render*` FIELD DEFINITION BUILT FOR ONE ROW, kept while the row is called with the same things
 * (2026-10-12).
 *
 * A table calls its `renderCell` (a list its `renderItem`) for every row on every render, and each call built
 * the cell anew: two `cloneDeep`s of the definition, its handlers, its props. Everything in a cell was a new
 * object or function each time, so the cell's field rendered again on every render of the table whenever it
 * took one as a prop, such as a Select's options or a handler with arguments. In a 200-row table, each edit of
 * one row's text rendered all 200 Selects of another column.
 *
 * A row's cell is now built once and kept for as long as the row is called with the very same things: the
 * same value, at the same index and path, with the same props from the caller, the same column label, and the
 * same caller methods standing in for handler names. What the build reads besides those belongs to the meta,
 * which is built anew with these renderers when the document's state changes. The element is still made anew
 * from the kept cell on every call, so the cell still renders, and still reads at render what it reads there,
 * such as a `showIf` or a field's value.
 */
type BuiltCell = { value: unknown, relativePath: unknown, label: unknown, props: Meta | undefined, callerHandlers: Meta, cell: Meta }

/** Whether two flat objects hold the very same values under the same keys. */
function sameValues (a: Meta | undefined, b: Meta | undefined): boolean {
    if (a === b) return true
    if (!a || !b) return false
    const keys = Object.keys(a)
    return keys.length === Object.keys(b).length
        && keys.every(key => Object.prototype.hasOwnProperty.call(b, key) && Object.is(a[key], b[key]))
}

/**
 * Map Data by given Mapper definition
 *
 * @param {Array|*} data - to map
 * @param {Object|String} mapper - object of key / value pairs (value being key path from `data`), or key path string
 * @param {Boolean} [debug] - whether to raise silenced error if data is missing or of incorrect type
 * @returns {Array} list - mapped from given data
 */
export function mapProps (data: unknown, mapper: string | Record<string, string>, {debug}: { debug?: boolean } = {}) {
    const mapData = typeof mapper === 'string' ? (item: unknown) => get(item, mapper, item) : (item: unknown, index: number) => {
        const result: Record<string, unknown> = {}
        for (const key in mapper) {
            // `index` must be converted to string to match fallback value defined in config (which can only be string)
            // fallback to item if key not found
            result[key] = mapper[key] === '{index}' ? String(index) : get(item, mapper[key], item)
        }
        return result
    }
    // A cast, not a guard: in debug mode the data is used as it is, and a non-list throws, as it did.
    return ((debug ? data : toList(data, true)) as unknown[]).map(mapData)
}

/** Exported for its unit tests: no other module imports it. */
export function getCurrencySymbol(currencyCode: unknown) {
    if (!currencyCode) return null
    switch (currencyCode) {
        case 'USD':
            return '$'
        case 'EUR':
            return '€'
        case 'GBP':
            return '£'
        default:
            return null
    }
}

/**
 * The symbol a `Currency` renderer prints: a `symbol` its definition gives, or else the symbol of its
 * `currencyCode`, or of the document's, which is the code itself when `getCurrencySymbol` knows none.
 * Every form of the renderer reads it here. Until 2026-10-06 only `{name: 'Currency'}` at the top of a
 * `render*` attribute took the document's currency, the string form and the forms inside `values`
 * printed `$` whatever it was, a `symbol` of the definition's own was replaced, and an unknown code
 * printed none.
 */
function currencySymbolFor (definition: Meta | undefined, instance: TransformConfig['instance']): unknown {
    if (definition && definition.symbol != null) return definition.symbol
    const currencyCode = (definition && definition.currencyCode) || (instance && instance.state && instance.state.currencyCode)
    return getCurrencySymbol(currencyCode) || currencyCode || undefined
}

/**
 * Recursively map meta.json declarations to props ready for rendering (by mutation)
 * @Note: this function must only transform config, without adding data.
 *  Because data is added at runtime on Render.
 *
 * @param {Object} meta - json
 * @param {*} config
 * @returns {Object} props - mutated meta
 */
export function metaToProps (this: unknown, meta: Meta, config: TransformConfig): Meta {
    const {
        form,
        instance, // contains dynamic `state` to hydrate meta data
        relativePath,
        relativeIndex,
        funcConfig,
    } = config
    let {data, _data} = config
    // Transform Root attributes
    if (isObject(meta)) {
        // Contract declarations (UPGRADE-PLAN §9.4) and author comments, not component props:
        // `$schema` points an editor at the published meta.schema.json, `metaVersion` records
        // which contract the file was authored against, `_comment` is a note to the next author.
        // Dropped here — the one place every node passes through on its way from meta.json to
        // props, nested nodes included — because every attribute the engine does not consume is
        // spread onto the resolved component and reaches the DOM: measured, a surviving
        // `metaVersion` renders as `metaversion="1"` and makes React warn about an unrecognised
        // prop, `$schema` trips React's invalid-attribute-name warning, and `_comment` rendered
        // the author's prose into the page as `_comment="…"` (2 occurrences in the example
        // corpus). Safe to mutate: `rules.tsx` hands metaToProps a cloneDeep of the host's meta,
        // never the host's object. `_comment` is also listed in components/domProps.ts, which
        // covers the nodes a component builds from raw meta without passing through here.
        NON_PROP_ATTRIBUTES.forEach(attribute => {
            if (meta[attribute] !== undefined) delete meta[attribute]
        })
        metaToFunctions(meta, {...funcConfig, data, instance})
        if (meta.name) meta.name = interpolateString(meta.name, instance, {suppressError: true})
    }

    for (const attribute in meta) {
        // Skip `meta` json config for nested UI Render instances
        if (attribute === 'meta') continue
        const definition = meta[attribute]
        if (!definition) continue

        // Map `onClick` functions by name (if exists)
        // @Note: high priority, because onClick string will be bound to `self` class inside `render` functions
        if (isObject(definition)) {
            // @Note: `relativePath` is deliberately NOT forwarded here. It reaches `getFunctionFromObject`,
            // which puts it into the `popupOpen` context, where `rules.tsx` gives it the highest priority when
            // resolving popup field names — rebinding a root-level popup template onto the table's path.
            // A `render*` view definition's own handlers are resolved where it renders, below, with the row's
            // index: bound here, once and outside any row, an `{index}` in their arguments stayed as written.
            if (!(attribute.indexOf('render') === 0 && definition.view)) {
                metaToFunctions(definition, {...funcConfig, data, relativeIndex, _data, rowValue: _data, instance})
            }
            if (definition.name) {
                definition.name = interpolateString(definition.name, instance, {suppressError: true})
            }
        }

        // Map Value Renderer Names/Objects to Actual Render Functions
        if (attribute.indexOf('render') === 0) {
            if (typeof definition === 'string') {
                // Not undefined: the mapper installs `Render.Method` when the engine loads.
                const method = Render.Method!(definition)
                meta[attribute] = (definition === FIELD.RENDER.CURRENCY && method)
                    ? (value: unknown, index: unknown, props?: Meta, ...rest: unknown[]) =>
                        method(value, index, {symbol: currencySymbolFor(undefined, instance), ...props}, ...rest)
                    : method
            }
            // Below transformation only happens during render
            // @Note: every renderer built in this loop closes over the ONE function-scoped `_data` binding and
            // reassigns it below, while the transform code further down (the `definition.name` lookup and the
            // nested-definition `options._data`) reads that same binding. Renderers therefore observe, and can
            // clobber, each other's scratch value. Behaviour is intact today only because each renderer assigns
            // before it reads. Scoping this per renderer is engine-decomposition work (§9.3), not a lint fix.
            // What the definition's own handlers were resolved against before they were resolved per call.
            const contextData = _data
            // This renderer's cells, by row (see `BuiltCell`).
            const builtCells = new Map<unknown, BuiltCell>()
            // eslint-disable-next-line no-loop-func
            if (isObject(definition)) meta[attribute] = (value: any, index: any, props: Meta, self: any, column?: { label?: string }) => {
                if (attribute === 'renderExtraItem') {
                    definition.useForm = true
                }

                if (definition.relativeData === false) {
                    _data = data
                } else {
                    _data = value
                }

                // Render is a field definition
                if (definition.view) {
                    const {name, filterItems, ...declared} = definition
                    // TableView calls renderExtraItem(allItems) with no row index — `index` is undefined.
                    // Inputs must bind to the next array slot (allItems.length): e.g. lineItems[2].field, not lineItems.field.
                    let rowIndex = index
                    if (attribute === 'renderExtraItem' && rowIndex == null && isCollection(value)) {
                        rowIndex = value.length
                    }
                    const revPath: { relativeIndex: unknown, relativePath?: string } = {
                        relativeIndex: rowIndex
                    }
                    // `meta.name` is undefined when Table.headers.renderCell is defined,
                    // this leads to nested Table with incorrect Input.name, which relies on correct `relativePath`.
                    // The condition is met when:
                    //    - meta.name === undefined
                    //    - relativePath != null
                    //    - relativeIndex != null
                    //    - self.props.name !== relativePath.split('.').pop() // when Table is nested inside List
                    // And requires Table.name to be appended to existing `relativePath`:
                    //    `${relativePath}.${relativeIndex}.${Table.name}`
                    // @solution: extract Table.name from class instance `self` because `meta` only has parent config.
                    if (
                      meta.name == null && relativePath != null && relativeIndex != null &&
                      self && self.props && self.props.name !== relativePath.split('.').pop()
                    ) {
                        revPath.relativePath = relativePathFrom(self.props, relativePath, relativeIndex)
                    } else {
                        revPath.relativePath = relativePathFrom(meta, relativePath, relativeIndex)
                    }

                    // Inject functions by their name string
                    // Pass index, value, and relativePath for args interpolation and context
                    // relativePath is critical for popup fields to have correct field names matching table row
                    const callerHandlers: Meta = removeNilValues(FUNCTION_NAMES.map(func => isString(definition[func]) && self &&
                      !getFunctionFromString(definition[func], {
                        ...funcConfig,
                        fallback: null,
                        relativeIndex: rowIndex,
                        relativePath: revPath.relativePath,
                        _data: value,
                        rowValue: value
                      }) &&
                      {[func]: self[definition[func]]}
                    )).reduce((obj: Meta, item: Meta) => ({...obj, ...item}), {})
                    const label = column && column.label
                    const kept = builtCells.get(rowIndex)
                    if (
                      kept && Object.is(kept.value, value) && kept.relativePath === revPath.relativePath && kept.label === label &&
                      sameValues(kept.props, props) && sameValues(kept.callerHandlers, callerHandlers)
                    ) {
                        return Render(kept.cell, rowIndex)
                    }

                    // The definition's own handlers, for this call: with the row's index and value when the
                    // caller passes an index (a table row), and with the context around it otherwise, as before.
                    const configs = cloneDeep(declared)
                    metaToFunctions(configs, {
                        ...funcConfig, data, instance,
                        relativeIndex: index != null ? index : relativeIndex,
                        _data: index != null ? value : contextData,
                        rowValue: index != null ? value : contextData,
                    })
                    const cell: Meta = {
                        // Relative Path is required for nested Inputs
                        ...revPath,
                        ...props,
                        // A field in a table cell, with no name of its own, is named by its column's header. Until
                        // 2026-10-09 it had none, and most of the nameless controls the examples rendered were these.
                        ...label && isUnnamedField(definition) && {'aria-label': label},
                        // Recursively map definitions within Render function
                        // Note: since definition is mutated on each transform,
                        // we have to use original config for rendering lists
                        // Pass index and value for args interpolation in onClick handlers
                        ...metaToProps(cloneDeep(configs), {...config, ...revPath, data, _data: value || _data, relativeIndex: rowIndex, rowValue: value}),
                        // Transform key path with actual data
                        ...name && {name: interpolateString(definition.name, {index: rowIndex, value})},
                        ...definition.index && {index: interpolateString(definition.index, {index: rowIndex})},
                        ...definition.useForm && {useForm: true},
                        // Filter for row data from parent table (in default layout)
                        ...filterItems && {filterItems, parentItem: value},
                        ...callerHandlers,
                        ...definition.view.indexOf('Data') === 0 && {index: rowIndex},
                        // A table's draft row: its form holds what the user types until Add, which is not the
                        // document's data yet (`dataFormsOf`). A `Data` node only, the one view that reads it.
                        ...attribute === 'renderExtraItem' && definition.view.indexOf('Data') === 0 && {draftRow: true},
                        data, _data, form, instance,
                    }
                    builtCells.set(rowIndex, { value, relativePath: revPath.relativePath, label, props, callerHandlers, cell })
                    return Render(cell, rowIndex)
                }

                // Render is a function definition
                else if (definition.name) {
                    const func = getFunctionFromObject(definition, {...funcConfig, data})
                    return isFunction(func) ? func.apply(this, [value, index, {...props, ...definition, symbol: currencySymbolFor(definition, instance), data, _data}])
                      : func
                }

                // Render is conditional match by values definitions
                else if (definition.values) {
                    const valueDefinition = definition.values[value] || definition.default
                    if (!valueDefinition) return value
                    return (isObject(valueDefinition))
                      ? (valueDefinition.view
                          ? Render({...props, ...valueDefinition, data, _data}, index)
                          : getFunctionFromObject(valueDefinition, {...funcConfig, data})
                            .apply(this, [value, index, {...props, ...valueDefinition, symbol: currencySymbolFor(valueDefinition, instance), data, _data}])
                      )
                      // Not undefined: the mapper installs `Render.Method`, which resolves every
                      // built-in renderer name.
                      : Render.Method!(valueDefinition)!.apply(this, [value, index, {symbol: currencySymbolFor(undefined, instance), ...props, data, _data}])
                }
            }
        }

        // Process nested Object/List definitions
        else if (isCollection(definition)) {
            const attrCount = Object.keys(definition).length
            if ( // this condition check must match exact case immediately, so that other cases get transformed
              attribute !== 'showIf' && definition.name != null &&
              (attrCount === 1 || (attrCount === 2 && definition.relativeData != null))
            ) {
                // Value Transform {name} - single key objects with name to their values
                // fallback to `name` attribute for transformed values from `state` (i.e. Tab.index, Dropdown.value...)
                // noinspection PointlessBooleanExpressionJS
                meta[attribute] = isString(definition.name)
                  ? get((definition.relativeData !== false && _data) || data, definition.name, definition.name)
                  : definition.name
                // Leave this to help users debug unresolved values
                if (meta[attribute] === definition.name && isString(definition.name) && isNaN(+definition.name)) {
                    // meta.view is equal to undefined in case of table headers (in some cases)
                    // in other cases no need to display label name
                    if (meta.view !== undefined) {
                        meta[attribute] = "";
                    }
                    // console.warn(`${meta.view}.${attribute}`, definition, '\n❌ Not found! relative _data:', _data)
                }
            } else {
                // Recursively process the rest of definitions
                // Relative path must always be passed down, because nested Inputs inside List require absolute path for `name`
                const options: Partial<TransformConfig> = {
                    data, _data, instance,
                    relativePath: relativePathFrom(meta, relativePath, relativeIndex), relativeIndex,
                    relativeData: meta.relativeData // Pass relativeData down to prevent automatic data extraction
                }
                // Resolve local `_data` for nested definitions
                // Only extract data by name if relativeData is not explicitly false
                // This prevents popup fields from accidentally getting the entire array instead of a single element
                if (meta.relativeData !== false && meta.name != null) {
                    options._data = get(_data || data, meta.name, _data)
                }
                meta[attribute] = metaToProps(meta[attribute], {...config, ...options})
            }
        }
    }

    // Pass down relative path to nested views
    if (meta.view) {
        if (relativePath != null && meta.relativePath == null) meta.relativePath = relativePath
        if (relativeIndex != null && meta.relativeIndex == null) meta.relativeIndex = relativeIndex
    }

    return meta
}

/**
 * THE VALIDATOR A `verify` COMPOSES, kept per document while its rules stay the same (2026-10-12).
 *
 * `metaToProps` runs on every render of a document, and a `verify` made a new validator each time. A
 * field takes it as its `validate` prop, so the field host's memo saw a changed prop on every render
 * of the document: every field with a `verify` rendered again on each change, a blur included. In a
 * 200-row period table that was all 402 date fields for one blur. The same rules give the same
 * function now: what the `verify` holds, and the field's own `validate`. A `verify` holding what JSON
 * cannot tell apart, a function for one, still makes a new validator on each render.
 *
 * A rule is looked up by name when the validator runs, in the registry of the document's latest
 * render, as the validator it replaces did: a field validates with the `validate` of its latest render.
 */
const keptVerify = new WeakMap<object, { registry: Record<string, Handler>, byRules: Map<string, { own: unknown, composed: Handler }> }>()

/** How many rule sets one document keeps. A host that keeps changing a document's meta starts over past it. */
const KEPT_VERIFY_LIMIT = 64

/** A document's kept validators, with the registry of its current render. */
function keptVerifyOf (instance: object, registry: Record<string, Handler>) {
    let kept = keptVerify.get(instance)
    if (!kept) {
        kept = { registry, byRules: new Map() }
        keptVerify.set(instance, kept)
    }
    kept.registry = registry
    return kept
}

const NOT_JSON = {}

/** A `verify` as a key, or `undefined` when it holds what JSON would not tell apart. */
function verifyKey (verify: Meta): string | undefined {
    try {
        return JSON.stringify(verify, function (this: Record<string, unknown>, key: string, value: unknown) {
            const held = this[key]
            if (typeof held === 'function' || typeof held === 'symbol') throw NOT_JSON
            if (typeof held === 'number' && !Number.isFinite(held)) throw NOT_JSON
            if (held !== null && typeof held === 'object' && !Array.isArray(held)) {
                const prototype = Object.getPrototypeOf(held)
                if (prototype !== Object.prototype && prototype !== null) throw NOT_JSON
            }
            return value
        })
    } catch (error) {
        return undefined
    }
}

/**
 * Transform Function Definition strings to actual methods, if they exist, by mutation
 * @example:
 *    const definition = {onChange: 'functionName'}
 *    >>> {onChange: Function}
 *
 * @param {Object} definition - containing function names
 * @param {Object} config
 * @returns {void} definition - with names replaced by functions (by mutation)
 */
function metaToFunctions(definition: Meta, config: FunctionConfig) {
    const {
        fieldValidation,
        fieldNormalizer,
        fieldParser,
        fieldFunc,
        funcNames = FUNCTION_NAMES
    } = config
    /* react-final-form does not support validate as array */
    // const validations = toList(definition.validate)
    // if (isString(validations[0])) definition.validate = removeNilValues(validations.map(id => FIELD.VALIDATION[id]))
    if (isString(definition.format)) definition.format = fieldNormalizer[definition.format]
    if (isString(definition.parse)) definition.parse = fieldParser[definition.parse] || fieldNormalizer[definition.parse]
    if (isString(definition.normalize)) definition.normalize = fieldNormalizer[definition.normalize]
    if (isString(definition.validate)) definition.validate = fieldValidation[definition.validate]
    if (hasObjectValue(definition.verify)) {
        // in the future, verify can have multiple validator functions, so compose them
        const {validate, ...opt} = definition.verify
        const { instance } = config
        const own = definition.validate
        const rules = instance !== null && typeof instance === 'object' ? verifyKey(definition.verify) : undefined
        const kept = rules === undefined ? undefined : keptVerifyOf(instance, fieldValidation)
        const reused = kept && kept.byRules.get(rules as string)
        if (reused && reused.own === own) {
            definition.validate = reused.composed
        } else {
            const registry = () => kept ? kept.registry : fieldValidation
            // final-form passes (value, allValues, meta) to field validate — forward for cross-field rules (e.g. notWithinRange)
            const validators = toList(validate).map(({name, ...args}: Meta) => (...validateArgs: unknown[]) => {
                const fn = registry()[name]
                return fn ? fn(validateArgs[0], {...opt, ...args}, validateArgs[1], validateArgs[2], instance) : undefined
            })
            if (own) validators.unshift(own)
            definition.validate = composeValidators(...validators)
            if (kept) {
                if (kept.byRules.size >= KEPT_VERIFY_LIMIT) kept.byRules.clear()
                kept.byRules.set(rules as string, { own, composed: definition.validate })
            }
        }
        delete definition.verify
    }
    funcNames.forEach(name => {
        if (isString(definition[name])) {
            definition[name] = getFunctionFromString(definition[name], {fieldFunc})
        } else if (isObject(definition[name])) {
            definition[name] = getFunctionFromObject(definition[name], config)
        }
    })
}

const composeValidators = (...validators: Handler[]) => (...args: unknown[]) => validators.reduce((error, validator) => error || validator(...args), undefined)

/**
 * Get Function/s from Definition Object Recursively
 * @example:
 *    getFunctionFromObject({name: 'reset', args: [0], onDone: 'setState,active.plan'})
 *    >>> function (...argumentsSuppliedFromCaller) {
 *          return setState(reset(...argumentsSuppliedFromCaller, 0), 'active.plan')
 *        }
 *
 * @param {Object<name, args, onDone>} definition - of function to call
 *    - @param {String} name - of the function
 *    - @param {Array} [args] - last arguments to pass to the function
 *    - @param {String|Object} [onDone] - callback recursive function definitions
 * @param {Object} config
 * @returns {Function|String} method - that receives caller arguments as its first arguments,
 *    and will chain function calls `onDone` recursively
 */
function getFunctionFromObject(definition: Meta, config: FunctionConfig): any {
    const {name, mapArgs, args = [], onDone} = definition
    const {data, fieldFunc, fieldMethods, fallback = definition.name, relativeIndex, _data, rowValue} = config
    const func = fieldFunc[name] || fieldMethods[name]
    if (onDone) metaToFunctions(definition, config)
    
    // Interpolate args if they contain template variables and we have index/value context
    let interpolatedArgs = args
    if (args.length > 0 && (relativeIndex != null || rowValue != null || _data != null)) {
        interpolatedArgs = args.map((arg: unknown) => {
            if (isString(arg) && arg.includes('{')) {
                return interpolateString(arg, { index: relativeIndex, value: rowValue || _data }, { suppressError: true })
            }
            return arg
        })
    }
    
    // For popupOpen, pass the row index through options so popup fields can address the table row.
    // @Note: deliberately NOT relativePath — see the metaToFunctions call above.
    const contextOptions: { relativeIndex?: unknown } = {}
    if (relativeIndex != null) contextOptions.relativeIndex = relativeIndex
    
    if (func) {
        const hasMapArgs = isList(mapArgs)
        // For popupOpen, merge context options with existing options
        // This ensures popup fields use the same relativePath and relativeIndex as the table row
        let finalArgs = interpolatedArgs
        if (name === 'popupOpen' && Object.keys(contextOptions).length > 0) {
            if (interpolatedArgs.length > 0 && typeof interpolatedArgs[interpolatedArgs.length - 1] === 'object' && interpolatedArgs[interpolatedArgs.length - 1] !== null) {
                // Merge with existing options object
                finalArgs = [...interpolatedArgs.slice(0, -1), {...interpolatedArgs[interpolatedArgs.length - 1], ...contextOptions}]
            } else {
                // Add options as second argument (id is first)
                finalArgs = [...interpolatedArgs, contextOptions]
            }
        }
        
        if (isFunction(definition.onDone)) {
            return (...values: unknown[]) => {
                if (hasMapArgs) {
                    values = mapArgs.map((val: unknown) => mapFunctionArgs(val, {data, args: values}))
                }
                const result = func(...values, ...finalArgs)
                if (result instanceof Promise) {
                    return result.then(definition.onDone)
                }
                return definition.onDone(result)
            }
        } else {
            return (...values: unknown[]) => {
                if (hasMapArgs) {
                    values = mapArgs.map((val: unknown) => mapFunctionArgs(val, {data, args: values}))
                }
                return func(...values, ...finalArgs)
            }
        }
    }
    // Not undefined: the mapper installs `Render.Method` when the engine loads.
    return func || Render.Method!(name) || fallback
}

/**
 * Get Function from Definition String
 * @example:
 *    getFunctionFromString('reset,0', {fieldFunc: FIELD.FUNC})
 *    >>> function reset(...argumentsSuppliedFromCaller, '0') {...}
 *
 * @param {String} string - name of function to get, with optional arguments, separated by comma
 * @param {*} config
 * @returns {Function|String|*} method - that receives caller arguments as its first arguments,
 *    along with optionally defined arguments in the config string
 */
function getFunctionFromString (string: string, {fieldFunc, fallback = string}: { fieldFunc: Record<string, Handler>, fallback?: unknown, [key: string]: unknown }) {
    const [name, ...args] = string.split(',')
    const func = fieldFunc[name]
    return ((args.length && func) ? ((...arg: unknown[]) => func(...arg, ...args)) : func) || fallback
}

/**
 * Map function arguments definition to actual values
 * @param {*} template - for the argument to be transformed
 * @param {*} options
 * @returns {*} argument transformed with given options
 */
function mapFunctionArgs (template: any, {data, args}: { data?: unknown, args: unknown[] }): unknown {
    if (isString(template))
        // Casts, not guards: `{0}` reads the first argument, and the data is the document's object.
        return interpolateString(interpolateString(template, args as unknown as Record<string, unknown>, {suppressError: true}), data as Record<string, unknown> | undefined, {suppressError: true})
    if (isCollection(template)) {
        // A copy, not the template (2026-10-12): a handler maps its arguments on every call, and the
        // template is the definition's own, kept as long as the handler is. Mapped in place, a second call
        // found the first call's values where the placeholders had been.
        const mapped: any = Array.isArray(template) ? [] : {}
        for (const key in template) {
            mapped[key] = mapFunctionArgs(template[key], {data, args})
        }
        return mapped
    }
    return template
}

/**
 * Compute Relative Path for given config
 * @param {Object|*[]|*} meta - config of the parent node
 * @param {String} relativePath - inherited from parent node
 * @param {String|Number} relativeIndex - inherited from parent node
 * @returns {String} relativePath - calculated from root path for current config
 */
export function relativePathFrom (meta: Meta, relativePath?: string, relativeIndex?: number | string): string {
    let result = relativePath || meta.name
    // If `meta.name` is relative, concatenate it with inherited `relativePath` for absolute relative path,
    // to pass down to nested configs (ex. Expand inside Table.headers = [{id, renderCell: {...}}] )
    if (meta.name != null && meta.relativeData !== false) {
        if (relativePath != null) {
            if (relativeIndex != null && relativeIndex !== '') {
                result = `${relativePath}.${relativeIndex}.${meta.name}`
            } else if (meta.name === relativePath || (isString(meta.name) && meta.name.startsWith(`${relativePath}.`))) {
                result = meta.name
            } else {
                result = `${relativePath}.${meta.name}`
            }
        } else {
            result = meta.name
        }
    }
    return result
}
