import classNames from '../utils/classNames'
import React, { useEffect, useRef, useState } from 'react'
import DropDown from './Listbox'
import type { ListboxCloseEvent, ListboxOption } from './Listbox'
import { l, localiseTranslation } from '../utils'
import { phrase } from '../utils/phrases'
import Icon from './Icon'
import Text from './Text'
import View from './View'
import { Active } from '../utils'
import { ENGINE_PROPS, FIELD_ONLY_PROPS, omitProps } from './domProps'
import type { Translate } from '../utils/_envs'
import type { PhraseMessage } from '../utils/phrases'

/** An option as a caller gives it: a string (translated), a number, or an object with `text`. */
export type DropdownOption = string | number | ListboxOption

/** What `onChange` and `onSelect` are called with. A reset by the cascading effect has no event. */
export type DropdownCallback = (value: unknown, name: string | undefined, event?: ListboxCloseEvent) => void

/** The named props are read here; the rest is passed to the `Listbox` it renders. */
export type DropdownProps = {
  value?: unknown
  /** An absent or null list renders an empty select */
  options?: DropdownOption[] | null
  onChange?: DropdownCallback
  onSelect?: DropdownCallback
  label?: string
  /** Translated by `translate`; without one, the select shows the built-in phrase `SELECT` */
  placeholder?: string
  done?: boolean
  /** Shown under the field: a string, which `translate` translates, or a validator's built-in phrase (`PhraseMessage`) */
  error?: React.ReactNode | PhraseMessage
  info?: React.ReactNode
  float?: boolean
  className?: string
  classNameIcon?: string
  style?: React.CSSProperties
  fill?: boolean
  lazyLoad?: boolean
  optionsLabel?: React.ReactNode
  initialValues?: unknown
  readonly?: boolean
  onClickIcon?: React.MouseEventHandler<HTMLElement>
  required?: boolean
  translate?: Translate
  /** Not read here: it rides the rest bag, and is what the callbacks report */
  name?: string
  [key: string]: unknown
}

localiseTranslation({
  ADD_: {
    [l.ENGLISH]: 'Add ',
  },
  NOTHING_FOUND: {
    [l.ENGLISH]: 'Nothing found',
  },
  NO_OPTIONS_LEFT: {
    [l.ENGLISH]: 'No options left',
  }
})

/**
 * NAMES `semantic-ui-react`'s Dropdown CONSUMED AND THIS ONE DOES NOT.
 *
 * Removing a feature is not the whole job: SUIR's Dropdown declared every one of these as a
 * handled prop, so passing one used to be quietly harmless. `Listbox` has an open rest spread onto
 * its dropdown element, so without this strip they would become ATTRIBUTES — measured, not
 * feared: `required` rendered as `required=""` on a div, and `clearable` produced React's
 * "Received `true` for a non-boolean attribute" warning. Failing loudly with an actionable message
 * is better than either.
 *
 * `required` is deliberately NOT here: the wrapper reads it for its own `required` class
 * (see the `input--wrapper` composition), so it is consumed rather than dropped.
 *
 * Same mechanism as `Tooltip`'s list, and for the same reason — see docs/SUPPORTED-PROPS.md.
 */
export const DROPPED_PROPS = [
    // §9.7-F1 step 3 part 2 removed these three features, on the evidence that nothing declares
    // them, and these are all the names that belonged to them.
    'search', 'searchInput', 'searchQuery', 'onSearch', 'onSearchChange', 'deburr',
    'multiple',
    'allowAdditions', 'additionLabel', 'additionPosition', 'onAddItem',
    // Could not outlive `search`: the wrapper turned it into `searchInput={{autoFocus: true}}`.
    'autofocus',
    // Both were only ever shown while filtering.
    'noResultsMessage',
    // Never wrapper API, but reachable through the old rest spread and curated as tier 2 on
    // docs/SUPPORTED-PROPS.md: SUIR's clear-selection icon. Nothing in either corpus sets it.
    'clearable',
    // The other 34 names semantic-ui-react's `Dropdown` declared that the listbox neither reads nor stripped, added on
    // 2026-10-09: each reached the dropdown element as an attribute, a boolean one with React's "Received `true` for a
    // non-boolean attribute" warning (the 2026-10-08 audit counted them). Neither corpus sets any of them.
    // Its open, close and select machinery, which the WAI-ARIA select-only combobox pattern decides instead:
    'closeOnBlur', 'closeOnChange', 'closeOnEscape', 'defaultOpen', 'open', 'openOnFocus', 'selectOnBlur',
    'selectOnNavigation', 'wrapSelection', 'defaultUpward', 'direction', 'tabIndex',
    // Its style variants, classes the listbox does not emit:
    'basic', 'button', 'floating', 'fluid', 'inline', 'item', 'labeled', 'loading', 'pointing', 'scrolling', 'simple',
    // What served `search` and `multiple`, gone with them:
    'defaultSearchQuery', 'minCharacters', 'defaultSelectedLabel', 'selectedLabel', 'renderLabel', 'onLabelClick',
    // Its element and content overrides:
    'as', 'header', 'trigger', 'text', 'defaultValue',
]

const warnedDropped = new Set<string>()

/** `props` without the dropped names, warning once per name in development. */
function dropUnsupported (props: Record<string, unknown>) {
    const kept: Record<string, unknown> = {}
    Object.keys(props).forEach(key => {
        if (DROPPED_PROPS.indexOf(key) === -1) {
            kept[key] = props[key]
            return
        }
        if (process.env.NODE_ENV !== 'production' && !warnedDropped.has(key)) {
            warnedDropped.add(key)
            console.warn(
                `[ui-render] <Dropdown> ignores the \`${key}\` prop.`
                + ' semantic-ui-react handled it; the in-house listbox does not, and nothing in the'
                + ' product or in any audited meta used it. docs/SUPPORTED-PROPS.md says what it did.'
            )
        }
    })
    return kept
}

/**
 * Drop Down Select - Pure Component. `docs/SUPPORTED-PROPS.md` records what each prop does.
 *
 * @example:
 *  <Dropdown
 *    label="Snap"
 *    value={0.1}
 *    options={[0.1, 0.2, 0.3]}
 *    className="inline-block"
 *  />
 *
 * @param {*} value - selected option value
 * @param {Array} options - list of option values, e.g. ['value']
 * @param {Function} [onChange] - callback when user changes input value, receives value as argument
 * @param {Function} [onSelect] - callback when user selects an option, receives value as argument
 * @param {String} [label] - text to display next to input
 * @param {String} [placeholder] - text
 * @param {Boolean} [done] - whether input is completed
 * @param {String|Object} [error] - message to display
 * @param {String|Object} [info] - explanation message to display under input
 * @param {Boolean} [float] - whether display as float-label input
 * @param {Boolean} [readonly] - whether to disable input and add `readonly` css class
 * @param {String} [className] - css class to add
 * @param {Object} [style] - css styles to add
 * @param {Boolean} [fill] - whether to fill available width
 * @param {Boolean} [lazyLoad] - whether to defer rendering options until opened, default is true
 * @param {*} [optionsLabel] - extra label for dropdown options on the bottom
 * @param {*} [props] - other attributes, passed to the `Listbox` dropdown element
 * @returns {Object}
 */
export function Dropdown ({
  options: opts,
  onChange,
  onSelect,
  label,
  placeholder,
  done,
  error,
  info,
  float,
  className,
  classNameIcon,
  style,
  fill = true,
  lazyLoad = true,
  optionsLabel,
  initialValues, // not used, removing from DOM
  readonly,
  onClickIcon,
  // Read for the wrapper's own `required` class. Destructured rather than read off the rest bag
  // because it has to be CONSUMED: SUIR declared `required` as a handled prop, and `Listbox`
  // would put it on its dropdown element as `required=""`.
  required,
  translate = Active.translate,
  value: valueFromParent,
  ...props
}: DropdownProps) {
  // The options as the prop gives them, sanitised below. They were state until 2026-10-08, synced from the prop by
  // an effect, which only made the previous list render once more after every change: nothing has written to them
  // since §9.7-F1 step 3 part 2 removed additions, and nothing downstream keys on the list's identity.
  let options = opts
  // Starts at the parent's value, or else at the first option's.
  const [value, setValue] = useState(() => typeof valueFromParent !== 'undefined'
    ? valueFromParent
    // A cast, not a guard: a string or a number has no `value`, and reads `undefined`, as it did.
    : ((Array.isArray(opts) && opts[0] && (opts[0] as ListboxOption).value) || undefined)
  )
  // What the effect below last took from the parent: `null` until it first runs.
  const synced = useRef<{ value: unknown } | null>(null)
  const tempValue = useRef<unknown>()

  // Sync internal value with parent prop.
  // Skip on initial mount when valueFromParent is undefined to preserve defaultValue (first option).
  // A run with nothing new from the parent does nothing either: StrictMode runs a mount's effects
  // twice, and a mount flag cleared by the first run let the second replace the default with no
  // selection (§9.3 step 7, `Dropdown.strict-mode.test.js`).
  useEffect(() => {
    const mounting = synced.current === null
    if (!mounting && synced.current!.value === valueFromParent) return
    synced.current = {value: valueFromParent}
    if (mounting && typeof valueFromParent === 'undefined') return
    setValue(valueFromParent == null || valueFromParent === '' ? null : valueFromParent)
  }, [valueFromParent])

  // Reset value when options change and current value is no longer valid (e.g., cascading Select).
  //
  // @Note: TWO defects here, both found by the §9.7-F1 step 3 part 1 audit and both about what the
  //  HOST is told rather than what is displayed.
  //  (1) The reset used to emit `String(...)` of the option value, with arity 1 — so a host whose
  //      options carry numbers was told to select `'7'` where the option is `7`, and a host
  //      matching with `===` missed it. The values are now kept unstringified (the stringified
  //      copy remains, but only as the comparison key it always was), and the call carries the
  //      `(value, name, event)` signature the wrapper documents. There is no event for a
  //      programmatic reset, so the third argument is genuinely absent rather than faked.
  //  (2) The guard did not cover an EMPTY ARRAY. `String([])` is `''`, which is never in the
  //      option keys, so a `multiple` dropdown mounted with `value={[]}` was reset immediately:
  //      `onChange(firstOption)` before the user touched anything, a selection they never made.
  const validOptions = (Array.isArray(opts) ? opts : []).map(o => (
    (typeof o === 'string' || typeof o === 'number') ? o : (o.value != null ? o.value : o.text)
  ))
  const validOptionValues = validOptions.map(String)
  const optionValuesKey = validOptionValues.join('\n')
  const hasNoValue = (value: unknown) => value == null || value === '' || (Array.isArray(value) && !value.length)
  useEffect(() => {
    if (!onChange || !validOptionValues.length) return
    if (hasNoValue(valueFromParent)) return
    if (!validOptionValues.includes(String(valueFromParent))) {
      onChange(validOptions[0], props.name)
    }
  }, [optionValuesKey]) // eslint-disable-line react-hooks/exhaustive-deps

  // What this component adds for `Listbox` goes on a copy of the rest bag: the cascading-reset effect above reads
  // `props`, and a value an effect has used may not change afterwards in the render. Same keys, in the same order,
  // as when the additions were written onto the bag itself.
  const listboxProps: Record<string, unknown> = {...props}
  if (readonly) listboxProps.disabled = true // the inner control has no `readOnly`
  if (listboxProps.selection == null) listboxProps.selection = true

  // @Note: the comment below used to claim `undefined` options "pass through unchanged". They did
  //  not — `options[0]` on an absent or null list THREW, measured:
  //  `Cannot read properties of undefined (reading '0')` for a bare `{view: 'Dropdown', name: 'x'}`,
  //  and the same for null (which a `name`-bound data path can produce). Only `options: []` ever
  //  rendered. An empty select is a legitimate state — options not loaded yet, or a genuinely
  //  empty list — so absent and null are now that state instead of a thrown error the engine
  //  replaces the whole node with. Found by the §9.7-F1 step 3 part 1 audit.
  if (options == null) options = []

  // Sanitize. Any other typeof — boolean, function — passes through unchanged; the bare
  // `no default` comment below is `default-case`'s escape hatch, though the rule is off for TypeScript (eslint.config.js).
  // Casts: the first option's type is taken as every option's, as it was.
  switch (typeof options[0]) {
    case 'string':
      options = (options as string[]).map(value => ({text: translate(value), value}))
      break
    case 'number':
      options = options.map(value => ({text: String(value), value}))
      break
    case 'object':
      // `typeof null === 'object'`, so null must be excluded here or it lands in the array branch below and
      // becomes the string "null".
      if (options[0].value !== null && typeof options[0].value === 'object') { // value is an array (ex. Color)
        options = (options as ListboxOption[]).map(({ value, text, ...option }) => ({ value: String(value), text: translate(text), ...option }))
      } else if (typeof options[0].value === 'string') {
        options = (options as ListboxOption[]).map(({ value, text, ...option }) => ({ value: value, text: translate(text), ...option }))
      } else if (options[0].value == null) {
        // An option with no value takes its text as the value. The cascading-reset effect above already
        // treats text as that option's value, and the two must agree — otherwise the value it asks the
        // parent to select can never equal the value the option carries, and nothing appears selected.
        options = (options as ListboxOption[]).map(({ value, text, ...option }) => ({ value: value != null ? value : text, text: translate(text), ...option }))
      }
      break
    // no default
  }
  // @Note: part 1 fixed a duplication here — `onAddItem` wrote the label-appended array back into
  //  option state, so every addition appended the label again — and part 2 made that fix
  //  unnecessary by removing `allowAdditions`: nothing writes options back any more, so the copy
  //  the fix needed is gone with it. Recorded rather than deleted silently, because a fix
  //  disappearing is worth a reader knowing it was ever needed.
  if (optionsLabel) options = [...options, {key: '', text: '', content: optionsLabel, disabled: true}]

  // Only when there is help text to point at, so no `aria-describedby` in this product ever dangles.
  const helpId = (props.id && (error || info)) ? `${props.id}-help` : undefined

  // With `onClickIcon`, the icon is rendered here as a node that takes the click: the control has no
  // click callback for its icon. A cast, not a guard: `icon` is then the name of the icon to render.
  if (onClickIcon) listboxProps.icon = <Icon name={(listboxProps.icon as string | undefined) || 'dropdown'} onClick={onClickIcon} className={classNameIcon}/>

  // The two handlers are spread after the filtered bag, not written into it: they reach `tempValue`, a ref, and
  // the bag passes through two functions during the render, which must not be handed one. `Listbox` takes both
  // as its own props, so where they sit in the bag never mattered, and the strip lists name neither.
  const handlers: Record<string, unknown> = {}
  if (onChange || onSelect) {
    handlers.onChange = (event: React.SyntheticEvent, {value}: { value: unknown }) => {
      // @Note: this used to map a case-mismatched value back onto an existing option's value, and
      //  §9.7-F1 step 3 part 2 removed that with the rest of the free-text machinery — NOT because
      //  it belonged to it, but because measuring showed the branch had become unreachable. It
      //  only ever fired for a value the user TYPED; a value picked from the list is an option's
      //  own value, so nothing could differ in case. Keeping it would have been dead code behind a
      //  comment claiming otherwise, which is worse than either removing or fixing it.
      // Store value temporarily for onSelect event.
      tempValue.current = value
      setValue(value)
      onChange && onChange(value, props.name, event)
    }
  }

  if (onSelect) handlers.onClose = (event: ListboxCloseEvent) => onSelect(tempValue.current, props.name, event)


  // Sanitize Value (for Colors)
  let dropdownValue = value
  // An array VALUE, not a multi-selection: a colour option carries `[r, g, b]`, and the option
  // list's own values were stringified by the sanitiser, so the selected value has to match.
  if (Array.isArray(dropdownValue) && dropdownValue.length) dropdownValue = dropdownValue.join(',')

  /// Error handling
  // @Note: below logic only works as DropdownField with controlled value
  // From the value the parent controls. This read `props.value`, which never holds it — `value` is
  // taken out of the rest bag above — so `done` was always false, and the stylesheet's
  // `.input--wrapper.done` never applied: a `float` label sat over the selection it named
  // (`Dropdown.done-state.test.js`). `hasNoValue` is the effect's own test, so an empty multiple
  // selection is not complete either, as the original `multiple` branch meant.
  if (done == null) done = !error && !hasNoValue(valueFromParent)

  // Hoisted rather than nested inside `omitProps(...)`: `scripts/generate-wrapper-prop-reference.js`
  // reads the strip lists out of the `omitProps` call to document the DOM boundary, and its parser
  // takes the argument text up to the first `)`.
  const supported = dropUnsupported(listboxProps)

  return (
    <View className={classNames('input--wrapper', {
      float, done, labeled: label, 'fill-width': !props.compact && fill, required,
    }, className)} style={style}>
      {label && !float && <Text className="input__label">{translate(label)}</Text>}
      <DropDown
        // The control's name: its label, or, with none, the built-in phrase `SELECT_NAME`, "Select <name>", as the
        // native `Select` names its control. Without the fallback a select with no `label` had no accessible name at
        // all (15 in the examples, the 2026-10-08 audit). A meta's own `aria-label` or `aria-labelledby` rides the
        // spread below and wins.
        aria-label={label ? translate(label) : (props.name ? phrase(translate, 'SELECT_NAME', {name: String(props.name)}) : undefined)}
        aria-describedby={helpId}
        className={classNames({info, readonly})}
        // A cast, not a guard: the sanitiser made objects of strings and numbers, and anything
        // else passes through as it always did.
        options={options as ListboxOption[]}
        placeholder={placeholder === undefined ? phrase(translate, 'SELECT') : translate(placeholder)}
        error={!!error}
        lazyLoad={lazyLoad}
        value={dropdownValue}
        // DOM boundary: `Listbox` spreads whatever it does not destructure onto its dropdown
        // element (and `aria-*` onto the combobox inside it), as Semantic's Dropdown did (and neither declares a
        // `name`), so engine props and `name`/`label` would become attributes there. Filtered
        // here, without touching the `props.name` the handlers report to the host. `Listbox` strips
        // again at its own edge because that is where the element is; this strip is what keeps
        // engine props from reaching it at all. See ./domProps.ts.
        {...omitProps(supported, ENGINE_PROPS, FIELD_ONLY_PROPS)}
        {...handlers}
      />
      {label && float && <Text className="input__label">{translate(label)}</Text>}
      {(error || info) &&
      /*
       * `${id}-help`, not `id`. The caller's `id` also rides the rest bag onto the dropdown
       * element, so this View used to give TWO elements the same id — invalid, and
       * reachable without the caller doing anything, because `mapper.tsx` assigns `input.id`
       * automatically for relative paths. The derived id is also what `aria-describedby` on the
       * control now points at: the error and info text was rendered but never announced.
       * Found by the §9.7-F1 step 3 part 1 audit.
       */
      <View id={helpId} className="field-help">
        {error && <Text className="error" translate={translate}>{error}</Text>}
        {info && <Text className="info">{translate(info)}</Text>}
      </View>
      }
    </View>
  )
}

Dropdown.displayName = 'Dropdown'

export default React.memo(Dropdown)
