/**
 * STYLE VARIABLES =============================================================
 * Should match with colors defined in /style/_variables.less
 * =============================================================================
 */

/** The roles below the palette, assigned to its colors after it is built. */
type StyleRoles = Record<'PRIMARY' | 'PRIMARY_LIGHT' | 'SECONDARY' | 'SECONDARY_LIGHT', string>

/* Colors */
const palette = {
  ANIMATION_DURATION: 500,
  SIZE_SCALE: 62.5, // match percentage of font-size defined in <html> root element
  GREY: 'rgb(55, 145, 70)',
  TEXT: 'rgb(23,21,31)',
  TEXT_LIGHT: 'rgb(237, 237, 237)',
  BG: 'rgb(238,246,255)',
  BG_LIGHT: 'rgb(23,21,31)',
  TEAL: 'rgb(0, 172, 188)',
  TEAL_LIGHT: 'rgb(16, 165, 234)',
  GREEN: 'rgb(55, 145, 70)',
  GREEN_LIGHT: 'rgb(36, 210, 187)',
  GOLD: 'rgb(239, 165, 44)',
  GOLD_LIGHT: 'rgb(243, 200, 88)',
  YELLOW: 'rgb(250, 215, 88)',
  YELLOW_LIGHT: 'rgb(255, 237, 122)',
  ORANGE: 'rgb(229, 114, 37)',
  ORANGE_LIGHT: 'rgb(244, 150, 45)',
  RED: 'rgb(220, 30, 45)',
  RED_LIGHT: 'rgb(247, 111, 170)',
  PINK: 'rgb(235, 77, 164)',
  PINK_LIGHT: 'rgb(255, 125, 205)',
  VIOLET: 'rgb(90, 55, 187)',
  VIOLET_LIGHT: 'rgb(103, 118, 234)',
  BORDER: 'rgba(124, 124, 153, 0.3)',
  TRANSPARENT: 'rgba(0, 0, 0, 0)',
}
// A cast, not a guard: the four roles are assigned on the next lines, before anything can read them.
export const STYLE = palette as typeof palette & StyleRoles
STYLE.PRIMARY = STYLE.TEAL
STYLE.PRIMARY_LIGHT = STYLE.TEAL_LIGHT
STYLE.SECONDARY = STYLE.VIOLET
STYLE.SECONDARY_LIGHT = STYLE.VIOLET_LIGHT
