import classNames from '../utils/classNames'
import React, { useCallback, useRef, useState } from 'react'
import { capitalize, isString } from '../utils'
import Button from './Button'
import Icon from './Icon'
import InputNative from './InputNative'
import type { InputNativeElement } from './InputNative'
import Label from './Label'
import Row from './Row'
import Text from './Text'
import View from './View'
import { Active } from '../utils'
import type { Translate } from '../utils/_envs'
import type { PhraseMessage } from '../utils/phrases'
import { useOwnId } from './useOwnId'

/** The props documented on `Input` below; the rest is passed to `InputNative`. */
export type InputProps = {
  name?: string
  id?: string
  icon?: React.ReactNode
  lefty?: boolean
  onClickIcon?: React.MouseEventHandler<HTMLElement>
  unit?: string
  label?: string
  disabled?: boolean
  done?: boolean
  className?: string
  classNameIcon?: string
  children?: React.ReactNode
  stickyPlaceholder?: boolean
  resize?: boolean
  readonly?: boolean
  autofocus?: boolean
  float?: boolean
  /** Shown under the field: a string, which `translate` translates, or a validator's built-in phrase (`PhraseMessage`) */
  error?: React.ReactNode | PhraseMessage
  info?: React.ReactNode
  style?: React.CSSProperties
  onFocus?: (...args: unknown[]) => void
  onBlur?: (...args: unknown[]) => void
  onRemove?: (nameOrId: string | undefined) => void
  title?: string
  placeholder?: string
  translate?: Translate
  [key: string]: unknown
}

/**
 * Input Wrapper - Pure Component.
 * @Note: see `InputNative` component for more documentation
 *
 * @param {String} [name] - input name attribute
 * @param {String|Object|Boolean} [icon] - name or rendered component, rendered after input by default
 * @param {Boolean} [lefty] - whether to render icon on the left before input
 * @param {Function} [onClickIcon] - callback function when clicking on the icon if given
 * @param {Function} [onFocus] - callback when input gets focus
 * @param {Function} [onBlur] - callback when input loses focus
 * @param {Function} [onRemove] - callback(id || name) when input is deleted
 * @param {String} [unit] - text to display next to entered input value
 * @param {String} [label] - text to display next to input
 * @param {String} [id] - unique identifier for label
 * @param {Boolean} [float] - whether display as float-label input
 * @param {Boolean} [disabled] - whether input is disabled
 * @param {Boolean} [done] - whether input is completed
 * @param {Boolean} [stickyPlaceholder] - whether to persist placeholder as user types
 * @param {Boolean} [resize] - whether to adjust input height to match typed in text
 * @param {Boolean} [readonly] - whether to disable input and add `readonly` css class
 * @param {Boolean} [autofocus] - whether to make input focused on page load
 * @param {String|Object} [error] - message to display
 * @param {String|Object} [info] - explanation message to display under input
 * @param {String} [title] - tooltip
 * @param {String} [className] - css class to add
 * @param {String} [classNameIcon] - css class to add to Icon
 * @param {Object} [style] - css styles
 * @param {String|Object} [children] - React component
 * @param {*} props - attributes to pass to `<input />`
 * @returns {Object} - React Component
 */
export function Input ({
  name,
  id: idGiven,
  icon,
  lefty,
  onClickIcon,
  unit,
  label,
  disabled,
  done,
  className,
  classNameIcon,
  children,
  stickyPlaceholder, // only works with controlled component when `props.value` is provided
  resize,
  readonly,
  autofocus,
  float,
  error,
  info,
  style,
  onFocus,
  onBlur,
  onRemove,
  title,
  placeholder,
  translate = Active.translate,
  ...props
}: InputProps) {
  const [active, setState] = useState(props.autoFocus)
  // Fixed when the input mounts, as the ref it was until 2026-10-08.
  const [max] = useState(props.type === 'date' ? '9999-01-01' : null)
  if (autofocus) props.autoFocus = autofocus // React fix
  if (readonly) {
    props.className = 'readonly'
    props.readOnly = readonly
  } // React fix
  if (float) {
    if (!label && name) label = capitalize(name)
    if (!placeholder) placeholder = ' ' // required for Float label CSS to work
  }
  // The id as it always was: the one given, else the name, else, unless the input is hidden, one from the label.
  let derivedId = idGiven === undefined ? name : idGiven
  if (props.type !== 'hidden' && !derivedId && label) derivedId = 'input-' + label.replace(/ +?/g, '-')
  // Unique on the page unless the meta gave it: see `useOwnId`.
  const field = useRef<InputNativeElement | null>(null)
  const onField = useCallback((node: InputNativeElement | null) => { field.current = node }, [])
  const ownId = useOwnId(idGiven ? undefined : derivedId, field)
  const id = idGiven || ownId
  if (props.type === 'hidden') {
    return <InputNative name={name} id={id} disabled={disabled} elementRef={onField} {...props} />
  }
  if (!label && title) props.title = translate(title)
  // An `aria-describedby` naming an id no element carries is worse than none: it is an axe
  // `aria-valid-attr-value` violation, and a screen reader announces nothing for it. The help
  // element exists only while there is a message, so the reference is conditional on the same
  // value — one binding for both, so the two cannot disagree again.
  const idHelp = (error || info) ? id + '-help' : undefined
  const value = props.value != null ? props.value : props.defaultValue
  const valueText = value == null ? '' : String(value)
  const hasValue = value || value === 0
  const isCheckbox = props.type === 'checkbox'
  if (done == null) done = (!error && hasValue) as boolean // a cast: `classNames` reads only its truthiness
  return (
    <View
      className={classNames('input--wrapper', className, {
        float, done, resize, swatch: props.type === 'color', required: props.required
      })}
      style={style}
    >
      {!float &&
      <Row className="middle">
        {!isCheckbox && label && <Label htmlFor={id} title={translate(title)}>{translate(label)}</Label>}
        {onRemove && !readonly &&
        <Button className="input__delete" onClick={() => onRemove(name || id)}><Icon name="delete"/></Button>}
      </Row>
      }
      <Row className={classNames('input', {active, icon, lefty, error, info, unit})}>
        {icon && lefty && (isString(icon)
            ? <Icon name={icon} onClick={onClickIcon} className={classNameIcon}/>
            : icon
        )}
        {unit && hasValue &&
        <Text className='input__unit truncate'>
          <Text className='invisible' aria-hidden='true'>{value as React.ReactNode}</Text> {unit}
        </Text>
        }
        {stickyPlaceholder && placeholder && hasValue &&
        <Text className='input__unit' aria-hidden='true'>
          <Text className='invisible no-margin'>{valueText}</Text>{placeholder.substring(valueText.length)}
        </Text>
        }
        <InputNative
          name={name} id={id} disabled={disabled} resize={resize} aria-describedby={idHelp} elementRef={onField}
          onFocus={(...args: unknown[]) => {
            !active && setState(true)
            onFocus && onFocus(...args)
          }}
          onBlur={(...args: unknown[]) => {
            active && setState(false)
            onBlur && onBlur(...args)
          }}
          max={max}
          placeholder={translate(placeholder)}
          {...props}
        />
        {icon && !lefty && (isString(icon)
            ? <Icon name={icon} onClick={onClickIcon} className={classNameIcon}/>
            : icon
        )}
        {(float || isCheckbox) && label && <Label htmlFor={id} title={translate(title)}>{translate(label)}</Label>}
      </Row>
      {idHelp &&
      <View id={idHelp} className='field-help'>
        {error && <Text className='error' translate={translate}>{error}</Text>}
        {info && <Text className='info'>{translate(info)}</Text>}
      </View>
      }
      {/* Reserved for Tooltip or other things */}
      {children}
    </View>
  )
}

export default React.memo(Input)
